set<pair<int, int>> s;

void f(int L, int R) {
  if (L == R) {
    s.insert(make_pair(L, R));
    return;
  }
  int m = (L + R) / 2;
  for (int i = L; i <= m; i++) s.insert(make_pair(i, m));
  for (int i = m + 1; i <= R; i++) s.insert(make_pair(m + 1, i));
  f(L, m);
  f(m + 1, R);
  return;
}
